
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS simulation_runs (run_id TEXT PRIMARY KEY, seed INTEGER, started_at TEXT, timezone TEXT, status TEXT, total_ticks INTEGER, current_tick INTEGER, merchant_count INTEGER, customer_count INTEGER, catalog_source TEXT, created_at TEXT);
CREATE TABLE IF NOT EXISTS run_state (run_id TEXT PRIMARY KEY REFERENCES simulation_runs(run_id), state_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS merchants (merchant_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), name TEXT, district TEXT, category TEXT, position INTEGER, starting_cash_cents INTEGER, source TEXT, paypal_account_mapping TEXT);
CREATE TABLE IF NOT EXISTS products (product_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), merchant_id TEXT REFERENCES merchants(merchant_id), channel3_product_id TEXT, title TEXT, brand TEXT, category TEXT, currency TEXT, price_cents INTEGER, cost_cents INTEGER, source TEXT, source_url TEXT, image_url TEXT, initial_stock INTEGER, cost_assumption TEXT, retrieved_at TEXT);
CREATE TABLE IF NOT EXISTS customers (customer_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), segment TEXT, budget_cents INTEGER, source TEXT);
CREATE TABLE IF NOT EXISTS campaigns (campaign_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), merchant_id TEXT REFERENCES merchants(merchant_id), name TEXT, channel TEXT, objective TEXT, daily_budget_cents INTEGER, status TEXT, policy TEXT, creative TEXT);
CREATE TABLE IF NOT EXISTS events (event_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), event_ts TEXT, event_date TEXT, merchant_id TEXT REFERENCES merchants(merchant_id), customer_id TEXT REFERENCES customers(customer_id), product_id TEXT REFERENCES products(product_id), campaign_id TEXT REFERENCES campaigns(campaign_id), order_id TEXT, channel TEXT, event_type TEXT, detail_json TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS orders (order_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), merchant_id TEXT REFERENCES merchants(merchant_id), customer_id TEXT REFERENCES customers(customer_id), campaign_id TEXT REFERENCES campaigns(campaign_id), event_ts TEXT, event_date TEXT, channel TEXT, currency TEXT, subtotal_cents INTEGER, discount_cents INTEGER, shipping_cents INTEGER, total_cents INTEGER, cost_cents INTEGER, delivery_cost_cents INTEGER, status TEXT, source TEXT, sandbox_requested INTEGER);
CREATE TABLE IF NOT EXISTS order_items (order_item_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), order_id TEXT REFERENCES orders(order_id), product_id TEXT REFERENCES products(product_id), quantity INTEGER, unit_price_cents INTEGER, line_total_cents INTEGER);
CREATE TABLE IF NOT EXISTS transactions (transaction_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), order_id TEXT UNIQUE REFERENCES orders(order_id), merchant_id TEXT REFERENCES merchants(merchant_id), event_ts TEXT, event_date TEXT, currency TEXT, gross_cents INTEGER, fee_cents INTEGER, net_cents INTEGER, status TEXT, source TEXT, fee_assumption TEXT);
CREATE TABLE IF NOT EXISTS refunds (refund_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), order_id TEXT UNIQUE REFERENCES orders(order_id), transaction_id TEXT REFERENCES transactions(transaction_id), merchant_id TEXT REFERENCES merchants(merchant_id), event_ts TEXT, event_date TEXT, amount_cents INTEGER, currency TEXT, reason TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS deliveries (delivery_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), order_id TEXT UNIQUE REFERENCES orders(order_id), merchant_id TEXT REFERENCES merchants(merchant_id), event_ts TEXT, event_date TEXT, units INTEGER, status TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS inventory_movements (movement_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), product_id TEXT REFERENCES products(product_id), merchant_id TEXT REFERENCES merchants(merchant_id), order_id TEXT REFERENCES orders(order_id), event_ts TEXT, event_date TEXT, quantity INTEGER, reason TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS campaign_spend (spend_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), campaign_id TEXT REFERENCES campaigns(campaign_id), merchant_id TEXT REFERENCES merchants(merchant_id), event_ts TEXT, event_date TEXT, channel TEXT, amount_cents INTEGER, currency TEXT, source TEXT);
CREATE TABLE IF NOT EXISTS paypal_receipts (receipt_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id), order_id TEXT UNIQUE REFERENCES orders(order_id), merchant_id TEXT REFERENCES merchants(merchant_id), profile_key TEXT, status TEXT, paypal_order_id TEXT UNIQUE, capture_id TEXT UNIQUE, payee_merchant_id TEXT, currency TEXT, gross_cents INTEGER, fee_cents INTEGER, net_cents INTEGER, created_at TEXT, captured_at TEXT, verified_at TEXT, event_date TEXT, error_code TEXT, create_request_id TEXT, capture_request_id TEXT, funding_method TEXT, funding_key TEXT, source TEXT DEFAULT 'PAYPAL_SANDBOX');
CREATE INDEX IF NOT EXISTS events_run_date ON events(run_id,event_date,event_type);
CREATE INDEX IF NOT EXISTS orders_run_date ON orders(run_id,event_date,merchant_id);
CREATE INDEX IF NOT EXISTS transactions_run ON transactions(run_id,event_date);
CREATE INDEX IF NOT EXISTS campaign_spend_run ON campaign_spend(run_id,campaign_id,event_date);
CREATE VIEW IF NOT EXISTS v_marketing_transactions AS SELECT t.transaction_id,t.run_id,t.event_ts,t.event_date,t.order_id,t.merchant_id,m.name AS merchant_name,m.district,o.customer_id,u.segment AS customer_segment,o.campaign_id,c.name AS campaign_name,o.channel,t.currency,t.gross_cents,t.fee_cents,t.net_cents,COALESCE(r.amount_cents,0) AS refunded_cents,o.cost_cents,o.delivery_cost_cents,t.net_cents-COALESCE(r.amount_cents,0)-o.cost_cents-o.delivery_cost_cents AS contribution_before_marketing_cents,t.source,p.status AS sandbox_status,p.paypal_order_id,p.capture_id,p.gross_cents AS sandbox_gross_cents,p.fee_cents AS sandbox_fee_cents,p.net_cents AS sandbox_net_cents,p.captured_at AS sandbox_captured_at FROM transactions t JOIN orders o USING(order_id) JOIN merchants m ON m.merchant_id=t.merchant_id JOIN customers u ON u.customer_id=o.customer_id LEFT JOIN campaigns c ON c.campaign_id=o.campaign_id LEFT JOIN refunds r ON r.order_id=t.order_id LEFT JOIN paypal_receipts p ON p.order_id=t.order_id;
CREATE VIEW IF NOT EXISTS v_daily_merchant_sales AS WITH sales AS (SELECT run_id,event_date,merchant_id,COUNT(*) AS purchases,SUM(gross_cents) AS gross_cents,SUM(fee_cents) AS fee_cents,SUM(refunded_cents) AS refunds_cents,SUM(contribution_before_marketing_cents) AS contribution_cents FROM v_marketing_transactions GROUP BY run_id,event_date,merchant_id), spend AS (SELECT run_id,event_date,merchant_id,SUM(amount_cents) AS ad_spend_cents FROM campaign_spend GROUP BY run_id,event_date,merchant_id), keys AS (SELECT run_id,event_date,merchant_id FROM sales UNION SELECT run_id,event_date,merchant_id FROM spend) SELECT k.run_id,k.event_date,k.merchant_id,m.name AS merchant_name,COALESCE(s.purchases,0) AS purchases,COALESCE(s.gross_cents,0) AS gross_cents,COALESCE(s.fee_cents,0) AS fee_cents,COALESCE(s.refunds_cents,0) AS refunds_cents,COALESCE(s.contribution_cents,0) AS contribution_cents,COALESCE(a.ad_spend_cents,0) AS ad_spend_cents,COALESCE(s.contribution_cents,0)-COALESCE(a.ad_spend_cents,0) AS contribution_after_marketing_cents FROM keys k JOIN merchants m USING(merchant_id) LEFT JOIN sales s ON s.run_id=k.run_id AND s.event_date=k.event_date AND s.merchant_id=k.merchant_id LEFT JOIN spend a ON a.run_id=k.run_id AND a.event_date=k.event_date AND a.merchant_id=k.merchant_id;
CREATE VIEW IF NOT EXISTS v_campaign_performance AS WITH traffic AS (SELECT run_id,campaign_id,COUNT(CASE WHEN event_type='impression' THEN 1 END) AS impressions,COUNT(CASE WHEN event_type='product_view' THEN 1 END) AS clicks,COUNT(CASE WHEN event_type='add_to_cart' THEN 1 END) AS carts FROM events GROUP BY run_id,campaign_id), sales AS (SELECT run_id,campaign_id,COUNT(*) AS purchases,SUM(gross_cents-refunded_cents) AS retained_revenue_cents,SUM(contribution_before_marketing_cents) AS contribution_cents FROM v_marketing_transactions GROUP BY run_id,campaign_id), spend AS (SELECT run_id,campaign_id,SUM(amount_cents) AS spend_cents FROM campaign_spend GROUP BY run_id,campaign_id) SELECT c.run_id,c.campaign_id,c.merchant_id,m.name AS merchant_name,c.name,c.channel,COALESCE(t.impressions,0) AS impressions,COALESCE(t.clicks,0) AS clicks,COALESCE(t.carts,0) AS carts,COALESCE(s.purchases,0) AS purchases,COALESCE(s.retained_revenue_cents,0) AS retained_revenue_cents,COALESCE(a.spend_cents,0) AS spend_cents,COALESCE(s.contribution_cents,0)-COALESCE(a.spend_cents,0) AS contribution_cents,ROUND(1.0*s.retained_revenue_cents/NULLIF(a.spend_cents,0),2) AS roas FROM campaigns c JOIN merchants m USING(merchant_id) LEFT JOIN traffic t ON t.campaign_id=c.campaign_id LEFT JOIN sales s ON s.campaign_id=c.campaign_id LEFT JOIN spend a ON a.campaign_id=c.campaign_id;
CREATE VIEW IF NOT EXISTS v_marketing_funnel AS SELECT run_id,event_date,merchant_id,channel,COUNT(CASE WHEN event_type='impression' THEN 1 END) AS impressions,COUNT(CASE WHEN event_type='product_view' THEN 1 END) AS product_views,COUNT(CASE WHEN event_type='add_to_cart' THEN 1 END) AS carts,COUNT(CASE WHEN event_type='purchase' THEN 1 END) AS purchases,COUNT(CASE WHEN event_type='cart_abandoned' THEN 1 END) AS abandoned_carts,COUNT(CASE WHEN event_type='stockout' THEN 1 END) AS stockouts FROM events GROUP BY run_id,event_date,merchant_id,channel;
CREATE VIEW IF NOT EXISTS v_inventory AS SELECT p.run_id,p.product_id,p.merchant_id,p.title,p.initial_stock,COALESCE(SUM(i.quantity),0) AS net_movement,p.initial_stock+COALESCE(SUM(i.quantity),0) AS on_hand FROM products p LEFT JOIN inventory_movements i USING(product_id) GROUP BY p.product_id;
CREATE VIEW IF NOT EXISTS v_customer_segments AS SELECT u.run_id,u.segment,COUNT(DISTINCT u.customer_id) AS customers,COUNT(DISTINCT t.order_id) AS purchases,COALESCE(SUM(t.gross_cents-t.refunded_cents),0) AS retained_revenue_cents FROM customers u LEFT JOIN v_marketing_transactions t USING(customer_id) GROUP BY u.run_id,u.segment;
CREATE TABLE IF NOT EXISTS marketing_planner_calls (call_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),budget_id TEXT,review_id TEXT,stage TEXT,attempt INTEGER,evidence_day INTEGER,decision_day INTEGER,decision_hour INTEGER,model TEXT,status TEXT,input_json TEXT,choice_json TEXT,provider_json TEXT,error_json TEXT,started_at TEXT,finished_at TEXT);
CREATE INDEX IF NOT EXISTS marketing_planner_calls_run ON marketing_planner_calls(run_id,started_at);
CREATE TABLE IF NOT EXISTS recommendation_models (model_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),day INTEGER,model_type TEXT,training_rows INTEGER,validation_purchases INTEGER,validation_from_day INTEGER,candidate_recall REAL,baseline_recall REAL,refit_rows INTEGER,dataset_hash TEXT,runtime_ms INTEGER,reason TEXT,artifact_json TEXT,source TEXT);
CREATE TABLE IF NOT EXISTS recommendations (recommendation_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),customer_id TEXT REFERENCES customers(customer_id),product_id TEXT REFERENCES products(product_id),merchant_id TEXT REFERENCES merchants(merchant_id),campaign_id TEXT REFERENCES campaigns(campaign_id),day INTEGER,event_date TEXT,model_id TEXT REFERENCES recommendation_models(model_id),decision_id TEXT,rank_score REAL,alternatives_json TEXT,reason TEXT,clicked INTEGER,order_id TEXT REFERENCES orders(order_id),outreach_cents INTEGER,source TEXT);
CREATE INDEX IF NOT EXISTS recommendations_run_customer ON recommendations(run_id,customer_id,day);
CREATE VIEW IF NOT EXISTS v_recommendation_journey AS SELECT r.run_id,r.recommendation_id,r.day,r.event_date,r.customer_id,r.merchant_id,r.product_id,p.title,p.channel3_product_id,r.model_id,r.decision_id,r.rank_score,r.reason,r.clicked,r.order_id,r.outreach_cents,o.total_cents,o.discount_cents,t.transaction_id,t.fee_cents AS modeled_fee_cents,t.net_cents AS modeled_net_cents,pr.paypal_order_id,pr.capture_id,pr.status AS sandbox_status,pr.gross_cents AS sandbox_gross_cents FROM recommendations r JOIN products p USING(product_id) LEFT JOIN orders o USING(order_id) LEFT JOIN transactions t ON t.order_id=r.order_id LEFT JOIN paypal_receipts pr ON pr.order_id=r.order_id;
CREATE TABLE IF NOT EXISTS business_goals (goal_id TEXT PRIMARY KEY,run_id TEXT UNIQUE REFERENCES simulation_runs(run_id),objective TEXT,question TEXT,budget_cents INTEGER,min_margin_pct REAL,contact_gap_days INTEGER,history_days INTEGER,followup_days INTEGER,policy TEXT,scenario TEXT,source TEXT);
CREATE TABLE IF NOT EXISTS campaign_assignments (assignment_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),campaign_id TEXT REFERENCES campaigns(campaign_id),customer_id TEXT REFERENCES customers(customer_id),assigned_day INTEGER,arm TEXT,propensity REAL,eligible INTEGER,source TEXT);
CREATE TABLE IF NOT EXISTS coupons (coupon_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),campaign_id TEXT REFERENCES campaigns(campaign_id),assignment_id TEXT REFERENCES campaign_assignments(assignment_id),customer_id TEXT REFERENCES customers(customer_id),merchant_id TEXT REFERENCES merchants(merchant_id),product_id TEXT REFERENCES products(product_id),issued_day INTEGER,expires_day INTEGER,discount_pct INTEGER,max_discount_cents INTEGER,model_id TEXT,reason TEXT,source TEXT);
CREATE TABLE IF NOT EXISTS coupon_redemptions (redemption_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),coupon_id TEXT UNIQUE REFERENCES coupons(coupon_id),order_id TEXT UNIQUE REFERENCES orders(order_id),customer_id TEXT REFERENCES customers(customer_id),event_date TEXT,discount_cents INTEGER,source TEXT);
CREATE TABLE IF NOT EXISTS customer_days (observation_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),customer_id TEXT REFERENCES customers(customer_id),day INTEGER,event_date TEXT,phase TEXT,product_id TEXT REFERENCES products(product_id),recency_days REAL,purchases_7d REAL,organic_14d REAL,visits_7d REAL,spend_7d REAL,offers_7d REAL,redemptions_14d REAL,price_cents REAL,stock_available REAL,rival_sale REAL,payday REAL,offered_pct INTEGER,assignment_probability REAL,visited INTEGER,purchased INTEGER,redeemed INTEGER,gross_cents INTEGER,discount_cents INTEGER,contribution_cents INTEGER,source TEXT);
CREATE TABLE IF NOT EXISTS model_runs (model_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),day INTEGER,version INTEGER,status TEXT,reason TEXT,model_type TEXT,features_json TEXT,dataset_hash TEXT,training_rows INTEGER,validation_rows INTEGER,train_through_day INTEGER,validation_from_day INTEGER,validation_through_day INTEGER,validation_log_loss REAL,baseline_log_loss REAL,champion_log_loss REAL,brier_score REAL,candidates_json TEXT,artifact_json TEXT,runtime_ms INTEGER,source TEXT);
CREATE TABLE IF NOT EXISTS model_scores (score_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),customer_id TEXT REFERENCES customers(customer_id),product_id TEXT REFERENCES products(product_id),day INTEGER,model_id TEXT REFERENCES model_runs(model_id),p_no_offer REAL,p_five REAL,p_ten REAL,chosen_pct INTEGER,expected_gain_cents REAL,source TEXT);
CREATE TABLE IF NOT EXISTS team_decisions (decision_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),day INTEGER,role TEXT,action TEXT,message TEXT,evidence_json TEXT,status TEXT,source TEXT);
CREATE TABLE IF NOT EXISTS retention_results (result_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),campaign_id TEXT REFERENCES campaigns(campaign_id),window_start INTEGER,window_end INTEGER,status TEXT,treatment_n INTEGER,control_n INTEGER,treatment_inactive INTEGER,control_inactive INTEGER,treatment_rate REAL,control_rate REAL,lift REAL,ci_low REAL,ci_high REAL,estimated_prevented REAL,source TEXT);
CREATE TABLE IF NOT EXISTS policy_comparisons (comparison_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),policy TEXT,compared_run_id TEXT,seed INTEGER,purchases INTEGER,gross_cents INTEGER,contribution_cents INTEGER,coupon_cost_cents INTEGER,outreach_cents INTEGER,redemptions INTEGER,model_trains INTEGER,source TEXT);
CREATE INDEX IF NOT EXISTS customer_days_training ON customer_days(run_id,day);
CREATE INDEX IF NOT EXISTS learning_scores_run ON model_scores(run_id,day);
CREATE INDEX IF NOT EXISTS learning_coupon_run ON coupons(run_id,issued_day);
CREATE INDEX IF NOT EXISTS learning_decisions_run ON team_decisions(run_id,day);
CREATE VIEW IF NOT EXISTS v_coupon_journey AS SELECT c.run_id,c.coupon_id,c.issued_day,c.customer_id,c.merchant_id,m.name AS merchant_name,c.campaign_id,c.product_id,p.channel3_product_id,p.title,c.discount_pct,c.model_id,c.reason,r.order_id,r.discount_cents,t.transaction_id,t.gross_cents,t.fee_cents,t.net_cents,CASE WHEN r.order_id IS NULL THEN 'EXPIRED_UNUSED' ELSE 'REDEEMED' END AS outcome,c.source FROM coupons c JOIN products p USING(product_id) JOIN merchants m ON m.merchant_id=c.merchant_id LEFT JOIN coupon_redemptions r USING(coupon_id) LEFT JOIN transactions t ON t.order_id=r.order_id;
CREATE VIEW IF NOT EXISTS v_learning_daily AS SELECT run_id,day,event_date,phase,COUNT(*) AS observations,SUM(visited) AS visits,SUM(purchased) AS purchases,SUM(CASE WHEN offered_pct>0 THEN 1 ELSE 0 END) AS targeted,SUM(redeemed) AS redemptions,SUM(gross_cents) AS gross_cents,SUM(discount_cents) AS discount_cents,SUM(contribution_cents) AS contribution_cents FROM customer_days GROUP BY run_id,day,event_date,phase;
CREATE VIEW IF NOT EXISTS v_model_history AS SELECT run_id,model_id,day,version,status,model_type,training_rows,validation_rows,validation_log_loss,baseline_log_loss,champion_log_loss,brier_score,runtime_ms,reason FROM model_runs;
CREATE VIEW IF NOT EXISTS v_retention_experiments AS SELECT run_id,campaign_id,window_start,window_end,status,treatment_n,control_n,treatment_inactive,control_inactive,treatment_rate,control_rate,lift,ci_low,ci_high,estimated_prevented FROM retention_results;
CREATE TABLE IF NOT EXISTS agent_workflows (workflow_id TEXT PRIMARY KEY,run_id TEXT UNIQUE REFERENCES simulation_runs(run_id),request_id TEXT UNIQUE,goal_hash TEXT,state_json TEXT,created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS agent_checkpoints (checkpoint_id TEXT PRIMARY KEY,workflow_id TEXT REFERENCES agent_workflows(workflow_id),run_id TEXT REFERENCES simulation_runs(run_id),request_id TEXT,input_hash TEXT,action TEXT,actor TEXT,status TEXT,attempts INTEGER,input_json TEXT,output_json TEXT,error_json TEXT,started_at TEXT,finished_at TEXT,UNIQUE(workflow_id,request_id));
CREATE TABLE IF NOT EXISTS campaign_plans (plan_id TEXT PRIMARY KEY,workflow_id TEXT REFERENCES agent_workflows(workflow_id),run_id TEXT REFERENCES simulation_runs(run_id),version INTEGER,model_id TEXT REFERENCES model_runs(model_id),status TEXT,plan_json TEXT,created_at TEXT,launched_at TEXT);
CREATE TABLE IF NOT EXISTS campaign_customer_decisions (decision_id TEXT PRIMARY KEY,workflow_id TEXT REFERENCES agent_workflows(workflow_id),run_id TEXT REFERENCES simulation_runs(run_id),plan_id TEXT REFERENCES campaign_plans(plan_id),customer_id TEXT REFERENCES customers(customer_id),product_id TEXT REFERENCES products(product_id),merchant_id TEXT REFERENCES merchants(merchant_id),day INTEGER,arm TEXT,model_id TEXT REFERENCES model_runs(model_id),eligibility TEXT,reason TEXT,p_no_offer REAL,p_five REAL,p_ten REAL,proposed_pct INTEGER,issued_pct INTEGER,coupon_id TEXT REFERENCES coupons(coupon_id),features_json TEXT,UNIQUE(workflow_id,customer_id,day));
CREATE INDEX IF NOT EXISTS campaign_trace_customer ON campaign_customer_decisions(workflow_id,customer_id,day);
CREATE TABLE IF NOT EXISTS planner_sessions (workflow_id TEXT PRIMARY KEY REFERENCES agent_workflows(workflow_id),run_id TEXT REFERENCES simulation_runs(run_id),model TEXT,status TEXT,spend_cap_micros INTEGER,state_json TEXT,created_at TEXT,updated_at TEXT);
CREATE TABLE IF NOT EXISTS planner_turns (turn_id TEXT PRIMARY KEY,workflow_id TEXT REFERENCES agent_workflows(workflow_id),run_id TEXT REFERENCES simulation_runs(run_id),turn_index INTEGER,status TEXT,input_json TEXT,decision_json TEXT,request_json TEXT,provider_json TEXT,error_json TEXT,checkpoint_id TEXT,started_at TEXT,finished_at TEXT,UNIQUE(workflow_id,turn_index));

CREATE TABLE IF NOT EXISTS paypal_operations (
  operation_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id),
  service TEXT NOT NULL, action TEXT NOT NULL, status TEXT NOT NULL,
  evidence_day INTEGER, actor TEXT, rationale TEXT, evidence_json TEXT,
  order_id TEXT, customer_id TEXT, product_id TEXT, merchant_id TEXT,
  amount_cents INTEGER, currency TEXT DEFAULT 'USD', provider_id TEXT,
  result_json TEXT, error_code TEXT, profile_key TEXT, request_id TEXT,
  created_at TEXT, updated_at TEXT, source TEXT DEFAULT 'PAYPAL_SANDBOX'
);
CREATE INDEX IF NOT EXISTS paypal_operations_run ON paypal_operations(run_id,service);
CREATE TABLE IF NOT EXISTS paypal_money_events (
  event_id TEXT PRIMARY KEY, run_id TEXT REFERENCES simulation_runs(run_id),
  operation_id TEXT REFERENCES paypal_operations(operation_id), order_id TEXT,
  customer_id TEXT, merchant_id TEXT, event_type TEXT, provider_id TEXT,
  status TEXT, amount_cents INTEGER, fee_cents INTEGER, currency TEXT,
  provider_at TEXT, recorded_at TEXT, source TEXT DEFAULT 'PAYPAL_SANDBOX'
);
CREATE INDEX IF NOT EXISTS paypal_money_events_run ON paypal_money_events(run_id);
CREATE VIEW IF NOT EXISTS v_paypal_agent_actions AS
SELECT o.run_id,o.operation_id,o.service,o.action,o.status,o.evidence_day,
o.actor,o.rationale,o.order_id,o.customer_id,o.merchant_id,o.product_id,
p.channel3_product_id,p.title AS product_title,o.amount_cents,o.currency,
o.provider_id,o.error_code,o.created_at,o.updated_at,o.source
FROM paypal_operations o LEFT JOIN products p ON p.product_id=o.product_id;

CREATE TABLE IF NOT EXISTS policy_lab_runs(run_id TEXT PRIMARY KEY REFERENCES simulation_runs(run_id),comparison_id TEXT,branch TEXT,settings_json TEXT,config_hash TEXT,created_at TEXT);
CREATE TABLE IF NOT EXISTS policy_lab_checkpoints(checkpoint_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),review_no INTEGER,day INTEGER,role TEXT,actor TEXT,status TEXT,input_hash TEXT,input_json TEXT,output_json TEXT,provider_json TEXT,cost_micros INTEGER,created_at TEXT,finished_at TEXT);
CREATE TABLE IF NOT EXISTS policy_lab_models(model_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),day INTEGER,cutoff_day INTEGER,window_days INTEGER,training_rows INTEGER,validation_rows INTEGER,mse REAL,baseline_mse REAL,runtime_ms REAL,artifact_json TEXT,source TEXT);
CREATE TABLE IF NOT EXISTS policy_lab_merchants(merchant_decision_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),day INTEGER,merchant_id TEXT REFERENCES merchants(merchant_id),max_offer_pct INTEGER,stock INTEGER,reason TEXT,evidence_json TEXT,source TEXT);
CREATE TABLE IF NOT EXISTS policy_lab_actions(action_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),day INTEGER,customer_id TEXT REFERENCES customers(customer_id),policy_version TEXT,model_id TEXT REFERENCES policy_lab_models(model_id),context_json TEXT,selected_action TEXT,eligible_json TEXT,propensity REAL,target_merchant_id TEXT REFERENCES merchants(merchant_id),actual_merchant_id TEXT REFERENCES merchants(merchant_id),order_id TEXT REFERENCES orders(order_id),offered_pct INTEGER,platform_support_cents INTEGER,outreach_cents INTEGER,matures_day INTEGER,reward_cents INTEGER,source TEXT,UNIQUE(run_id,day,customer_id));
CREATE TABLE IF NOT EXISTS policy_lab_daily(daily_id TEXT PRIMARY KEY,run_id TEXT REFERENCES simulation_runs(run_id),day INTEGER,orders INTEGER,gross_cents INTEGER,refunds_cents INTEGER,fee_cents INTEGER,platform_support_cents INTEGER,outreach_cents INTEGER,merchant_contribution_cents INTEGER,platform_proxy_cents INTEGER,offers INTEGER,recommendations INTEGER,source TEXT,UNIQUE(run_id,day));
CREATE INDEX IF NOT EXISTS policy_actions_maturity ON policy_lab_actions(run_id,matures_day,day);
CREATE INDEX IF NOT EXISTS policy_checkpoints_run ON policy_lab_checkpoints(run_id,review_no);
CREATE VIEW IF NOT EXISTS v_policy_customer_journey AS SELECT a.run_id,a.action_id,a.day,a.customer_id,a.policy_version,a.model_id,a.selected_action,a.propensity,a.offered_pct,a.target_merchant_id,a.actual_merchant_id,a.order_id,a.platform_support_cents,a.outreach_cents,a.matures_day,a.reward_cents,m.name AS merchant_name,p.title,p.channel3_product_id,p.source AS catalog_source,o.total_cents,t.transaction_id,t.fee_cents AS modeled_fee_cents,COALESCE(r.amount_cents,0) AS modeled_refund_cents,pp.paypal_order_id,pp.capture_id,pp.status AS paypal_status,pp.fee_cents AS paypal_fee_cents,pp.verified_at FROM policy_lab_actions a LEFT JOIN orders o USING(order_id) LEFT JOIN merchants m ON m.merchant_id=o.merchant_id LEFT JOIN order_items oi USING(order_id) LEFT JOIN products p USING(product_id) LEFT JOIN transactions t USING(order_id) LEFT JOIN refunds r USING(order_id) LEFT JOIN paypal_receipts pp USING(order_id);

CREATE INDEX IF NOT EXISTS order_items_run ON order_items(run_id);
CREATE INDEX IF NOT EXISTS order_items_order ON order_items(order_id);
CREATE INDEX IF NOT EXISTS deliveries_run ON deliveries(run_id);
CREATE INDEX IF NOT EXISTS inventory_movements_run ON inventory_movements(run_id);
CREATE INDEX IF NOT EXISTS refunds_run ON refunds(run_id);
CREATE INDEX IF NOT EXISTS coupon_redemptions_run ON coupon_redemptions(run_id);
CREATE INDEX IF NOT EXISTS coupon_redemptions_order ON coupon_redemptions(order_id);
CREATE INDEX IF NOT EXISTS campaign_assignments_run ON campaign_assignments(run_id);
CREATE VIEW IF NOT EXISTS v_paypal_order_lineage AS SELECT o.run_id,o.order_id,o.event_ts AS simulation_event_ts,o.event_date AS simulation_event_date,o.merchant_id,m.name AS merchant_name,o.customer_id,o.campaign_id,c.coupon_id,c.discount_pct,o.currency,o.total_cents AS simulated_gross_cents,t.fee_cents AS modeled_fee_cents,t.net_cents AS modeled_net_cents,p.receipt_id,p.funding_method,p.status AS paypal_status,p.paypal_order_id,p.capture_id,p.payee_merchant_id,p.gross_cents AS paypal_gross_cents,p.fee_cents AS paypal_fee_cents,p.net_cents AS paypal_net_cents,p.captured_at AS provider_captured_at,p.verified_at AS provider_verified_at,p.event_date AS provider_event_date,p.error_code,p.source AS payment_source,CASE WHEN p.status IN ('COMPLETED','PARTIALLY_REFUNDED','REFUNDED') AND p.gross_cents=o.total_cents AND p.currency=o.currency THEN 1 ELSE 0 END AS amount_verified,(SELECT group_concat(pr.channel3_product_id,', ') FROM order_items oi JOIN products pr USING(product_id) WHERE oi.order_id=o.order_id) AS channel3_product_ids,(SELECT group_concat(pr.title,' | ') FROM order_items oi JOIN products pr USING(product_id) WHERE oi.order_id=o.order_id) AS product_titles FROM paypal_receipts p JOIN orders o ON o.order_id=p.order_id JOIN merchants m ON m.merchant_id=o.merchant_id JOIN transactions t ON t.order_id=o.order_id LEFT JOIN coupon_redemptions cr ON cr.order_id=o.order_id LEFT JOIN coupons c ON c.coupon_id=cr.coupon_id;
